1705	// CLAUDE.md are documented as permitted to be the same file, and os.SameFile in runInitAgents can
1706	// only see that when both FileInfos describe the TARGET inode. Following it is safe because the
1707	// following is done by os.Root, which refuses a link that leaves the repository; containment, not
1708	// link rejection, is what keeps the write in the project root. path is carried alongside name only
1709	// so the error names the file the caller asked about.
1710	func inspectInstructionFile(root *os.Root, name, path string) (os.FileInfo, error) {
1711		info, err := statContainedFile(root, name)
