1725	// formats as permission bits ("d---------"), which tells whoever hit this nothing
1726	// about what to remove or move aside.
1727	func fileTypeName(mode os.FileMode) string {
1728		switch {
1729		case mode.IsDir():
1730			return "directory"
1731		case mode&os.ModeSymlink != 0:
1732			return "symlink"
1733		case mode&os.ModeNamedPipe != 0:
1734			return "named pipe"
1735		case mode&os.ModeSocket != 0:
1736			return "socket"
1737		case mode&os.ModeCharDevice != 0:
1738			return "character device"
1739		case mode&os.ModeDevice != 0:
1740			return "device"
1741		case mode&os.ModeIrregular != 0:
1742			return "irregular file"
1743		default:
1744			return mode.Type().String()
1745		}
1746	}
