 793	// isGitAdministrativeDirectory applies git's own is_git_directory() test to a repo-relative
 794	// directory: a HEAD, plus either the object and ref stores or the commondir/gitdir pointers a
 795	// linked worktree keeps instead of them.
 796	func isGitAdministrativeDirectory(root *os.Root, dir string) bool {
 797		if info, err := root.Stat(filepath.Join(dir, "HEAD")); err != nil || info.IsDir() {
 798			return false
 799		}
 800		objects, objectsErr := root.Stat(filepath.Join(dir, "objects"))
 801		refs, refsErr := root.Stat(filepath.Join(dir, "refs"))
 802		if objectsErr == nil && refsErr == nil && objects.IsDir() && refs.IsDir() {
 803			return true
 804		}
 805		for _, pointer := range []string{"commondir", "gitdir"} {
 806			if info, err := root.Stat(filepath.Join(dir, pointer)); err == nil && !info.IsDir() {
 807				return true
 808			}
 809		}
 810		return false
 811	}
