755	// gitDirSpellingReachesTheGitDir confirms with THIS filesystem the question sem.PathLandsInGitDir
756	// answers from the name alone.
757	//
758	// The fold is there because macOS and Windows resolve a repository-chosen link target
759	// case-insensitively, so a committed `CLAUDE.md -> .GIT/config` opens `.git/config` and an exact
760	// comparison would be a bypass on exactly the two platforms most development happens on. Where the
761	// kernel does NOT fold, that reasoning describes nothing: `.GIT` is then an ordinary directory no
762	// git command has ever used, and refusing a contained markdown landing inside it rejects a
763	// legitimate alias — `AGENTS.md -> .GIT/rules.md` — for a spelling alone.
764	//
765	// So the fold is kept and then CHECKED. An exact `.git` component is the git directory whatever
766	// the filesystem does. A case variant is one only when the two spellings open the same directory,
767	// which is a question for the filesystem rather than for the text. Anything unanswerable keeps the
768	// fold's answer, so this can only ever confirm a refusal the name rule already raised, never
769	// withdraw one it could not decide.
770	func gitDirSpellingReachesTheGitDir(root *os.Root, resolved string) bool {
771		components := splitPathComponents(resolved)
772		for i, component := range components {
773			if component == ".git" {
774				return true
775			}
776			if !strings.EqualFold(component, ".git") {
777				continue
778			}
779			spelled, spelledErr := root.Stat(filepath.Join(components[:i+1]...))
780			if spelledErr != nil {
781				// The variant names nothing that can be compared. On a folding filesystem it
782				// would name `.git` whenever `.git` exists, so this is either a case-sensitive
783				// filesystem with nothing there yet or an unreadable ancestry; neither is
784				// evidence, and the fold stands.
785				return true
